    71→    if (config.id) {
    72→        let porId = plantillas.find(p => p.id == config.id);
    73→        if (porId) return porId;
    74→    }
    75→
    76→    if (config.nombre) {
    77→        let porNombre = plantillas.find(p => p.name === config.nombre);
    78→        if (porNombre) return porNombre;
    79→    }
    80→
    81→    return null;
    82→}
    83→
    84→/**
    85→ * Verificar si WhatsApp está configurado
    86→ *
    87→ * @returns {Promise} Promesa con el estado de configuración
    88→ * @author Esperanza Olivo
    89→ */
    90→function verificarConfiguracionWhatsApp() {
