    94→        dataType: 'json'
    95→    });
    96→}
    97→
    98→/**
    99→ * Cargar plantillas de WhatsApp disponibles
   100→ *
   101→ * @returns {Promise} Promesa con las plantillas
   102→ * @author Esperanza Olivo
   103→ */
   104→function cargarPlantillasWhatsApp() {
