   169→/**
   170→ * Mostrar vista previa de una plantilla de WhatsApp
   171→ *
   172→ * @param {number} id ID de la plantilla
   173→ * @author Esperanza Olivo
   174→ */
   175→function mostrarPreviewPlantillaWhatsApp(id) {
   176→    if (!id) {
