   179→    }
   180→
   181→    let plantilla = plantillas_whatsapp_cargadas.find(p => p.id == id);
   182→
   183→    if (plantilla) {
   184→        let contenido = plantilla.content || '';
   185→        contenido = contenido.replace(/\{\{(\d+)\}\}/g, '<span class="badge bg-primary">Variable $1</span>');
   186→
   187→        $('#preview-plantilla-whatsapp').html(`
   188→            <div class="card bg-light">
   189→                <div class="card-body">
   190→                    <h6 class="card-subtitle mb-2 text-muted">
   191→                        <i class="bi bi-whatsapp text-success me-2"></i>Vista previa
