   193→                    <div class="card-text whatsapp-preview">
   194→                        ${contenido}
   195→                    </div>
   196→                    <div class="mt-2">
   197→                        <small class="text-muted">
   198→                            <i class="bi bi-info-circle me-1"></i>
   199→                            Las variables serán reemplazadas con los datos del candidato.
   200→                        </small>
   201→                    </div>
   202→                </div>
   203→            </div>
   204→        `);
   205→    }
   206→}
