   223→ * @author Esperanza Olivo
   224→ */
   225→function obtenerCanalComunicacionVacante() {
   226→    if (typeof vacante_datos !== 'undefined' && vacante_datos.canal_comunicacion) {
   227→        return vacante_datos.canal_comunicacion;
   228→    }
   229→
   230→    if (typeof window.vacante_edicion !== 'undefined' && window.vacante_edicion.canal_comunicacion) {
   231→        return window.vacante_edicion.canal_comunicacion;
