   353→ * @author Esperanza Olivo
   354→ */
   355→function obtenerValoresRealesPlantillaWhatsAppCandidatos() {
   356→    let nombre_empresa = 'Nombre de empresa';
   357→    let nombre_vacante = 'Nombre de vacante';
   358→    let nombre_etapa = 'Revisión HV';
   359→    let fecha_fin = '';
   360→
   361→    if (typeof window.vacante_edicion !== 'undefined' && window.vacante_edicion.empresa) {
   362→        nombre_empresa = window.vacante_edicion.empresa.nombre_comercial || window.vacante_edicion.empresa.razon_social || nombre_empresa;
   363→    } else if (typeof vacante_datos !== 'undefined' && vacante_datos.empresa) {
   364→        nombre_empresa = vacante_datos.empresa.nombre_comercial || vacante_datos.empresa.razon_social || nombre_empresa;
   365→    } else if (typeof empresa !== 'undefined' && empresa) {
   366→        nombre_empresa = empresa.nombre_comercial || empresa.razon_social || empresa.nombre || nombre_empresa;
   367→    }
   368→
   369→    if (typeof window.vacante_edicion !== 'undefined' && window.vacante_edicion.nombre_vacante) {
   370→        nombre_vacante = window.vacante_edicion.nombre_vacante;
   371→    } else if (typeof vacante_datos !== 'undefined' && vacante_datos.nombre_vacante) {
   372→        nombre_vacante = vacante_datos.nombre_vacante;
   373→    }
   374→
   375→    if (typeof etapas_vacante !== 'undefined' && etapas_vacante.length > 0) {
   376→        let primera_etapa = etapas_vacante.find(e => e.activa == 1);
   377→        if (primera_etapa) {
   378→            nombre_etapa = primera_etapa.nombre;
