   411→    });
   412→
   413→    contenido = contenido.replace(/\{\{(\d+)\}\}/g, '<span class="badge bg-secondary">Variable $1</span>');
   414→
   415→    $('#selector-plantillas-whatsapp-candidatos').html(`
   416→        <div class="mb-2">
   417→            <span class="badge bg-success"><i class="bi bi-check-circle me-1"></i>Plantilla: ${plantilla.name}</span>
   418→        </div>
   419→    `);
   420→
   421→    let variables_html = variables.length > 0 ? `
   422→        <div class="mt-3">
   423→            <small class="text-muted fw-semibold">Variables que se enviarán:</small>
   424→            <ul class="list-unstyled mt-1 mb-0">
   425→                ${variables.map(v => {
   426→                    let valor_real = valores_reales[v.nombre] || '(se completará automáticamente)';
   427→                    return `<li><small><span class="badge bg-primary me-1">{{${v.posicion}}}</span>${v.descripcion}: <strong class="text-success">${valor_real}</strong></small></li>`;
   428→                }).join('')}
   429→            </ul>
   430→        </div>
   431→    ` : '';
   432→
   433→    $('#preview-plantilla-whatsapp-candidatos').html(`
   434→        <div class="card bg-light">
   435→            <div class="card-body">
   436→                <h6 class="card-subtitle mb-2 text-muted">
   437→                    <i class="bi bi-whatsapp text-success me-2"></i>Vista previa del mensaje
   438→                </h6>
   439→                <div class="card-text whatsapp-preview">
   440→                    ${contenido}
   441→                </div>
   442→                ${variables_html}
   443→                <div class="mt-2">
   444→                    <small class="text-muted">
   445→                        <i class="bi bi-info-circle me-1"></i>
   446→                        El nombre del candidato se completará con sus datos al enviar.
   447→                    </small>
   448→                </div>
   449→            </div>
   450→        </div>
   451→    `);
   452→}
   453→
   454→/**
   455→ * Generar selector de plantillas WhatsApp para candidatos
   456→ *
   457→ * @param {Array} plantillas Lista de plantillas
   458→ * @returns {string} HTML del selector
   459→ * @author Esperanza Olivo
   460→ */
   461→function generarSelectorPlantillasWhatsAppCandidatos(plantillas) {
