/**
 * Archivo para manejar la integración con WhatsApp en vacantes
 * @author Esperanza Olivo
 */

let plantillas_whatsapp_cargadas = [];

const PLANTILLAS_WHATSAPP = {
    INICIAL: {
        nombre: 'invitacion_etapa_1',
        id: null,
        variables: [
            { posicion: 1, nombre: 'nombre_aplicante', descripcion: 'Nombre del aplicante' },
            { posicion: 2, nombre: 'nombre_empresa', descripcion: 'Nombre de la empresa' },
            { posicion: 3, nombre: 'nombre_vacante', descripcion: 'Nombre de la vacante' },
            { posicion: 4, nombre: 'nombre_etapa', descripcion: 'Nombre de la etapa' },
            { posicion: 5, nombre: 'fecha_fin_aplicacion', descripcion: 'Fecha fin de aplicación' },
            { posicion: 6, nombre: 'enlace', descripcion: 'Enlace' }
        ]
    },
    CONTRATADOS: {
        nombre: 'contratado',
        id: null,
        variables: [
            { posicion: 1, nombre: 'nombre_aplicante', descripcion: 'Nombre del aplicante' },
            { posicion: 2, nombre: 'nombre_empresa', descripcion: 'Nombre de la empresa' },
            { posicion: 3, nombre: 'nombre_vacante', descripcion: 'Nombre de la vacante' },
            { posicion: 4, nombre: 'nombre_etapa', descripcion: 'Nombre de la etapa' }
        ]
    },
    DESCARTADOS: {
        nombre: 'descartado',
        id: null,
        variables: [
            { posicion: 1, nombre: 'nombre_aplicante', descripcion: 'Nombre del aplicante' },
            { posicion: 2, nombre: 'nombre_empresa', descripcion: 'Nombre de la empresa' },
            { posicion: 3, nombre: 'nombre_vacante', descripcion: 'Nombre de la vacante' },
            { posicion: 4, nombre: 'nombre_etapa', descripcion: 'Nombre de la etapa' }
        ]
    }
};

/**
 * Obtener la configuración de plantilla de WhatsApp según la etapa
 *
 * @param {string} nombre_etapa Nombre de la etapa
 * @returns {Object} Configuración de la plantilla (nombre, id, variables)
 */
function obtenerConfigPlantillaWhatsApp(nombre_etapa) {
    if (nombre_etapa === 'Contratados') {
        return PLANTILLAS_WHATSAPP.CONTRATADOS;
    }
    if (nombre_etapa === 'Descartados') {
        return PLANTILLAS_WHATSAPP.DESCARTADOS;
    }
    return PLANTILLAS_WHATSAPP.INICIAL;
}

/**
 * Buscar plantilla de WhatsApp por nombre o ID
 *
 * @param {Array} plantillas Lista de plantillas disponibles
 * @param {Object} config Configuración de la plantilla a buscar
 * @returns {Object|null} Plantilla encontrada o null
 */
function buscarPlantillaWhatsApp(plantillas, config) {
    if (!plantillas || plantillas.length === 0) {
        return null;
    }

    if (config.id) {
        let porId = plantillas.find(p => p.id == config.id);
        if (porId) return porId;
    }

    if (config.nombre) {
        let porNombre = plantillas.find(p => p.name === config.nombre);
        if (porNombre) return porNombre;
    }

    return null;
}

/**
 * Verificar si WhatsApp está configurado
 *
 * @returns {Promise} Promesa con el estado de configuración
 * @author Esperanza Olivo
 */
function verificarConfiguracionWhatsApp() {
    return $.ajax({
        url: '/api/whatsapp/estado',
        type: 'GET',
        dataType: 'json'
    });
}

/**
 * Cargar plantillas de WhatsApp disponibles
 *
 * @returns {Promise} Promesa con las plantillas
 * @author Esperanza Olivo
 */
function cargarPlantillasWhatsApp() {
    return $.ajax({
        url: '/api/whatsapp/plantillas',
        type: 'GET',
        dataType: 'json'
    }).then(function(respuesta) {
        if (respuesta.data) {
            plantillas_whatsapp_cargadas = respuesta.data;
        }
        return respuesta;
    });
}

/**
 * Obtener una plantilla de WhatsApp por su ID
 *
 * @param {number} id ID de la plantilla
 * @returns {Promise} Promesa con la plantilla
 * @author Esperanza Olivo
 */
function obtenerPlantillaWhatsApp(id) {
    return $.ajax({
        url: `/api/whatsapp/plantillas/${id}`,
        type: 'GET',
        dataType: 'json'
    });
}

/**
 * Generar HTML del selector de plantillas de WhatsApp
 *
 * @param {Array} plantillas Lista de plantillas
 * @param {number|null} seleccionada ID de la plantilla seleccionada
 * @returns {string} HTML del selector
 * @author Esperanza Olivo
 */
function generarSelectorPlantillasWhatsApp(plantillas, seleccionada = null) {
    if (!plantillas || plantillas.length === 0) {
        return `
            <div class="alert alert-warning" role="alert">
                <i class="bi bi-exclamation-triangle me-2"></i>
                No hay plantillas de WhatsApp disponibles. Configura plantillas aprobadas en tu cuenta de WhatsApp Business.
            </div>
        `;
    }

    let opciones = plantillas.map(p => {
        let selected = seleccionada && p.id == seleccionada ? 'selected' : '';
        return `<option value="${p.id}" ${selected}>${p.name}</option>`;
    }).join('');

    return `
        <div class="row">
            <div class="col-12 mb-3">
                <label class="form-label text-body-2">Selecciona una plantilla de WhatsApp</label>
                <select class="form-select" id="plantilla_whatsapp_id" name="plantilla_whatsapp_id">
                    <option value="">Seleccionar plantilla...</option>
                    ${opciones}
                </select>
            </div>
            <div class="col-12" id="preview-plantilla-whatsapp"></div>
        </div>
    `;
}

/**
 * Mostrar vista previa de una plantilla de WhatsApp
 *
 * @param {number} id ID de la plantilla
 * @author Esperanza Olivo
 */
function mostrarPreviewPlantillaWhatsApp(id) {
    if (!id) {
        $('#preview-plantilla-whatsapp').html('');
        return;
    }

    let plantilla = plantillas_whatsapp_cargadas.find(p => p.id == id);

    if (plantilla) {
        let contenido = plantilla.content || '';
        contenido = contenido.replace(/\{\{(\d+)\}\}/g, '<span class="badge bg-primary">Variable $1</span>');

        $('#preview-plantilla-whatsapp').html(`
            <div class="card bg-light">
                <div class="card-body">
                    <h6 class="card-subtitle mb-2 text-muted">
                        <i class="bi bi-whatsapp text-success me-2"></i>Vista previa
                    </h6>
                    <div class="card-text whatsapp-preview">
                        ${contenido}
                    </div>
                    <div class="mt-2">
                        <small class="text-muted">
                            <i class="bi bi-info-circle me-1"></i>
                            Las variables serán reemplazadas con los datos del candidato.
                        </small>
                    </div>
                </div>
            </div>
        `);
    }
}

/**
 * Inicializar eventos del selector de plantillas WhatsApp
 *
 * @author Esperanza Olivo
 */
function inicializarEventosPlantillasWhatsApp() {
    $(document).off('change', '#plantilla_whatsapp_id').on('change', '#plantilla_whatsapp_id', function() {
        mostrarPreviewPlantillaWhatsApp($(this).val());
    });
}

/**
 * Obtener el canal de comunicación de la vacante actual
 *
 * @returns {string} Canal de comunicación ('correo' o 'whatsapp')
 * @author Esperanza Olivo
 */
function obtenerCanalComunicacionVacante() {
    if (typeof vacante_datos !== 'undefined' && vacante_datos.canal_comunicacion) {
        return vacante_datos.canal_comunicacion;
    }

    if (typeof window.vacante_edicion !== 'undefined' && window.vacante_edicion.canal_comunicacion) {
        return window.vacante_edicion.canal_comunicacion;
    }

    let canal_input = $('input[name="canal_comunicacion"]:checked');
    if (canal_input.length) {
        return canal_input.val();
    }

    return 'correo';
}

/**
 * Verificar si el canal de comunicación es WhatsApp
 *
 * @returns {boolean} True si es WhatsApp
 * @author Esperanza Olivo
 */
function esWhatsApp() {
    return obtenerCanalComunicacionVacante() === 'whatsapp';
}

/**
 * Guardar plantilla de WhatsApp para una etapa
 *
 * @param {number} etapa_id ID de la etapa
 * @param {number} plantilla_id ID de la plantilla de WhatsApp
 * @returns {Promise} Promesa con el resultado
 * @author Esperanza Olivo
 */
function guardarPlantillaWhatsAppEtapa(etapa_id, plantilla_id) {
    return $.ajax({
        url: `/etapas-vacantes/${etapa_id}/plantilla-whatsapp`,
        type: 'PUT',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            plantilla_whatsapp_id: plantilla_id
        },
        dataType: 'json'
    });
}

/**
 * Manejar guardado del formulario de plantilla de etapa para WhatsApp
 *
 * @returns {boolean} False para prevenir submit del form
 * @author Esperanza Olivo
 */
function guardarPlantillaEtapaWhatsApp() {
    let etapa_id = $('#modal-editar-plantilla-etapa #etapa_id').val();
    let plantilla_id = $('#selector-plantillas-whatsapp #plantilla_whatsapp_id').val();

    if (!plantilla_id) {
        mostrarToast('warning', 'Selecciona una plantilla de WhatsApp');
        return false;
    }

    guardarPlantillaWhatsAppEtapa(etapa_id, plantilla_id)
        .then(function(respuesta) {
            mostrarToast('success', respuesta.message || 'Plantilla guardada correctamente');
            $('#modal-editar-plantilla-etapa').modal('hide');

            let etapa = etapas_vacante.find(e => e.id == etapa_id);
            if (etapa) {
                etapa.plantilla_whatsapp_id = plantilla_id;
            }
        })
        .catch(function(error) {
            mostrarToast('danger', error.responseJSON?.message || 'Error al guardar la plantilla');
        });

    return false;
}

$(document).ready(function() {
    inicializarEventosPlantillasWhatsApp();
});

/**
 * Cargar plantilla de WhatsApp para agregar candidatos
 * Usa la plantilla configurada para invitación a etapa (inicio del proceso)
 *
 * @author Esperanza Olivo
 */
function cargarPlantillaWhatsAppCandidatos() {
    let config = PLANTILLAS_WHATSAPP.INICIAL;

    // Obtener valores reales para el preview
    let valores_reales = obtenerValoresRealesPlantillaWhatsAppCandidatos();

    cargarPlantillasWhatsApp().then(function(respuesta) {
        let plantillas = respuesta.data || [];
        let plantilla_encontrada = buscarPlantillaWhatsApp(plantillas, config);

        if (plantilla_encontrada) {
            mostrarPreviewPlantillaWhatsAppCandidatos(plantilla_encontrada, config.variables, valores_reales);
        } else if (plantillas.length > 0) {
            $('#selector-plantillas-whatsapp-candidatos').html(
                generarSelectorPlantillasWhatsAppCandidatos(plantillas)
            );
            inicializarEventosPlantillasWhatsAppCandidatos();
        } else {
            $('#selector-plantillas-whatsapp-candidatos').html(`
                <div class="alert alert-warning" role="alert">
                    <i class="bi bi-exclamation-triangle me-2"></i>
                    No hay plantillas de WhatsApp disponibles.
                </div>
            `);
        }
    }).catch(function(error) {
        $('#selector-plantillas-whatsapp-candidatos').html(`
            <div class="alert alert-danger" role="alert">
                <i class="bi bi-exclamation-triangle me-2"></i>
                Error al cargar las plantillas de WhatsApp.
            </div>
        `);
    });
}

/**
 * Obtener valores reales para el preview de plantilla WhatsApp de candidatos
 *
 * @returns {Object} Valores reales para cada variable
 * @author Esperanza Olivo
 */
function obtenerValoresRealesPlantillaWhatsAppCandidatos() {
    let nombre_empresa = 'Nombre de empresa';
    let nombre_vacante = 'Nombre de vacante';
    let nombre_etapa = 'Revisión HV';
    let fecha_fin = '';

    if (typeof window.vacante_edicion !== 'undefined' && window.vacante_edicion.empresa) {
        nombre_empresa = window.vacante_edicion.empresa.nombre_comercial || window.vacante_edicion.empresa.razon_social || nombre_empresa;
    } else if (typeof vacante_datos !== 'undefined' && vacante_datos.empresa) {
        nombre_empresa = vacante_datos.empresa.nombre_comercial || vacante_datos.empresa.razon_social || nombre_empresa;
    } else if (typeof empresa !== 'undefined' && empresa) {
        nombre_empresa = empresa.nombre_comercial || empresa.razon_social || empresa.nombre || nombre_empresa;
    }

    if (typeof window.vacante_edicion !== 'undefined' && window.vacante_edicion.nombre_vacante) {
        nombre_vacante = window.vacante_edicion.nombre_vacante;
    } else if (typeof vacante_datos !== 'undefined' && vacante_datos.nombre_vacante) {
        nombre_vacante = vacante_datos.nombre_vacante;
    }

    if (typeof etapas_vacante !== 'undefined' && etapas_vacante.length > 0) {
        let primera_etapa = etapas_vacante.find(e => e.activa == 1);
        if (primera_etapa) {
            nombre_etapa = primera_etapa.nombre;
        }
    }

    let fecha = new Date();
    fecha.setDate(fecha.getDate() + 7);
    fecha_fin = fecha.toLocaleDateString('es-CO');

    return {
        nombre_aplicante: 'Candidato',
        nombre_empresa: nombre_empresa,
        nombre_vacante: nombre_vacante,
        nombre_etapa: nombre_etapa,
        fecha_fin_aplicacion: fecha_fin,
        enlace: window.location.origin + '/ats/...'
    };
}

/**
 * Mostrar vista previa de plantilla WhatsApp para candidatos
 *
 * @param {Object} plantilla Datos de la plantilla
 * @param {Array} variables Lista de variables de la plantilla
 * @param {Object} valores_reales Valores reales para mostrar en el preview
 * @author Esperanza Olivo
 */
function mostrarPreviewPlantillaWhatsAppCandidatos(plantilla, variables = [], valores_reales = {}) {
    let contenido = plantilla.content || '';

    variables.forEach(function(v) {
        let regex = new RegExp('\\{\\{' + v.posicion + '\\}\\}', 'g');
        let valor_real = valores_reales[v.nombre] || v.descripcion;
        contenido = contenido.replace(regex, `<span class="badge bg-success" title="${v.descripcion}">${valor_real}</span>`);
    });

    contenido = contenido.replace(/\{\{(\d+)\}\}/g, '<span class="badge bg-secondary">Variable $1</span>');

    $('#selector-plantillas-whatsapp-candidatos').html(`
        <div class="mb-2">
            <span class="badge bg-success"><i class="bi bi-check-circle me-1"></i>Plantilla: ${plantilla.name}</span>
        </div>
    `);

    let variables_html = variables.length > 0 ? `
        <div class="mt-3">
            <small class="text-muted fw-semibold">Variables que se enviarán:</small>
            <ul class="list-unstyled mt-1 mb-0">
                ${variables.map(v => {
                    let valor_real = valores_reales[v.nombre] || '(se completará automáticamente)';
                    return `<li><small><span class="badge bg-primary me-1">{{${v.posicion}}}</span>${v.descripcion}: <strong class="text-success">${valor_real}</strong></small></li>`;
                }).join('')}
            </ul>
        </div>
    ` : '';

    $('#preview-plantilla-whatsapp-candidatos').html(`
        <div class="card bg-light">
            <div class="card-body">
                <h6 class="card-subtitle mb-2 text-muted">
                    <i class="bi bi-whatsapp text-success me-2"></i>Vista previa del mensaje
                </h6>
                <div class="card-text whatsapp-preview">
                    ${contenido}
                </div>
                ${variables_html}
                <div class="mt-2">
                    <small class="text-muted">
                        <i class="bi bi-info-circle me-1"></i>
                        El nombre del candidato se completará con sus datos al enviar.
                    </small>
                </div>
            </div>
        </div>
    `);
}

/**
 * Generar selector de plantillas WhatsApp para candidatos
 *
 * @param {Array} plantillas Lista de plantillas
 * @returns {string} HTML del selector
 * @author Esperanza Olivo
 */
function generarSelectorPlantillasWhatsAppCandidatos(plantillas) {
    let opciones = plantillas.map(p => `<option value="${p.id}">${p.name}</option>`).join('');

    return `
        <label class="form-label text-body-2">Selecciona una plantilla</label>
        <select class="form-select" id="selector_plantilla_whatsapp_candidatos">
            <option value="">Seleccionar...</option>
            ${opciones}
        </select>
    `;
}

/**
 * Inicializar eventos del selector de plantillas WhatsApp para candidatos
 *
 * @author Esperanza Olivo
 */
function inicializarEventosPlantillasWhatsAppCandidatos() {
    $(document).off('change', '#selector_plantilla_whatsapp_candidatos').on('change', '#selector_plantilla_whatsapp_candidatos', function() {
        let plantilla_id = $(this).val();

        if (plantilla_id) {
            let plantilla = plantillas_whatsapp_cargadas.find(p => p.id == plantilla_id);
            if (plantilla) {
                mostrarPreviewPlantillaWhatsAppCandidatos(plantilla);
            }
        } else {
            $('#preview-plantilla-whatsapp-candidatos').html('');
        }
    });
}

/**
 * Obtener la plantilla de WhatsApp correspondiente a una etapa
 *
 * @param {string} nombre_etapa Nombre de la etapa
 * @returns {Promise} Promesa con objeto { plantilla, config } o null
 * @author Esperanza Olivo
 */
function obtenerPlantillaWhatsAppPorEtapa(nombre_etapa) {
    let config = obtenerConfigPlantillaWhatsApp(nombre_etapa);

    return cargarPlantillasWhatsApp().then(function(respuesta) {
        let plantillas = respuesta.data || [];
        let plantilla = buscarPlantillaWhatsApp(plantillas, config);
        return plantilla ? { plantilla: plantilla, config: config } : null;
    });
}

