```php
/**
 * Notificar cambio de etapa por WhatsApp.
 *
 * @param User $usuario Candidato.
 * @param Vacante $vacante Vacante.
 * @param EtapaVacante $etapa Etapa de la vacante.
 * @param mixed $empresa Empresa.
 * @param int|null $etapa_vacante_usuario_id ID de la relación etapa-vacante-usuario.
 * @return array Resultado de la notificación.
 * @author [Tu nombre]
 */
private function notificarCambioEtapaWhatsApp(
    $usuario,
    Vacante $vacante,
    EtapaVacante $etapa,
    $empresa,
    ?int $etapa_vacante_usuario_id = null
): array {
    $nombre_candidato = trim($usuario->nombres . ' ' . $usuario->apellidos) ?: 'Candidato';

    if (empty($usuario->telefono)) {
        return [
            'exito' => false,
            'error' => 'El candidato no tiene número de teléfono registrado'
        ];
    }

    // Mapeo de etapas a nombres de plantillas de WhatsApp
    $plantilla_nombre = match($etapa->nombre) {
        EtapaVacante::CONTRATADOS_NOMBRE => 'contratado',
        EtapaVacante::DESCARTADOS_NOMBRE => 'descartado',
        default => 'invitacion_etapa_1'
    };

    $plantilla_whatsapp_id = $this->whatsapp_servicio->obtenerIdPlantillaPorNombre($plantilla_nombre);

    // Si no existe plantilla específica para contratados/descartados, usar la genérica
    if (!$plantilla_whatsapp_id && in_array($etapa->nombre, [EtapaVacante::CONTRATADOS_NOMBRE, EtapaVacante::DESCARTADOS_NOMBRE])) {
        $plantilla_whatsapp_id = $this->whatsapp_servicio->obtenerIdPlantillaPorNombre('invitacion_etapa_1');
    }

    if (!$plantilla_whatsapp_id) {
        return [
            'exito' => false,
            'error' => 'No se encontró la plantilla de WhatsApp'
        ];
    }

    $nombre_empresa = $empresa->nombre_comercial ?? $empresa->razon_social ?? 'La empresa';
    $nombre_vacante = $vacante->nombre_vacante ?? 'la vacante';

    // Variables según el tipo de plantilla
    if (in_array($etapa->nombre, [EtapaVacante::CONTRATADOS_NOMBRE, EtapaVacante::DESCARTADOS_NOMBRE])) {
        // Plantillas 'contratado' y 'descartado' tienen 4 variables
        $variables = [
            $nombre_candidato,       // {{1}} nombre_aplicante
            $nombre_empresa,         // {{2}} nombre_empresa
            $nombre_vacante,         // {{3}} nombre_vacante
            $etapa->nombre           // {{4}} nombre_etapa
        ];
    } else {
        // Plantilla 'invitacion_etapa_1' tiene 6 variables
        $token_acceso = $this->token_acceso_servicio->generar($usuario->id);
        $enlace       = request()->getSchemeAndHttpHost() . "/control-acceso/{$token_acceso->token}?vacante_id={$vacante->id}";

        $variables = [
            $nombre_candidato,                        // {{1}} nombre_aplicante
            $nombre_empresa,                          // {{2}} nombre_empresa
            $nombre_vacante,                          // {{3}} nombre_vacante
            $etapa->nombre ?? 'la etapa',             // {{4}} nombre_etapa
            Carbon::now()->addDays(7)->format('d/m/Y'), // {{5}} fecha_fin_aplicacion
            $enlace                                   // {{6}} enlace
        ];
    }

    try {
        $resultado = $this->whatsapp_servicio->enviarMensajePlantilla(
            $plantilla_whatsapp_id,
            $usuario->telefono,
            $variables,
            null,
            [],
            [],
            [
                'vacante_id'               => $vacante->id,
                'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
                'tipo'                     => match($etapa->nombre) {
                    EtapaVacante::CONTRATADOS_NOMBRE => 'contratado',
                    EtapaVacante::DESCARTADOS_NOMBRE => 'descartado',
                    default => 'cambio_etapa'
                },
                'metadata' => [
                    'etapa_id'     => $etapa->id,
                    'etapa_nombre' => $etapa->nombre,
                    'empresa_id'   => $empresa->id
                ]
            ]
        );

        return [
            'exito'      => $resultado['exito'] ?? false,
            'message_id' => $resultado['message_id'] ?? null
        ];
    } catch (\Exception $e) {
        return [
            'exito' => false,
            'error' => $e->getMessage()
        ];
    }
}
```

